import {mountLiveMarket} from './live-market.js';
import {mountDataHub} from './data-hub.js';
import {VoiceController} from './voice.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let markets=[],selected=null,filter='all',period='D',view='home',tasks=[],decisions=[],configured=false,toastTimer;
const api=async(path,body)=>{const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const j=await r.json();if(!r.ok)throw Error(j.error||'本地服务未响应');return j};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
const sourceList=[['SHFE','上海期货交易所','日行情 / 仓单 / 合约规则','https://www.shfe.com.cn/reports/tradedata/datadownload/'],['INE','上海国际能源交易中心','日周数据 / 结算参数','https://www.ine.cn/reports/tradedata/dailyandweeklydata/'],['DCE','大连商品交易所','合约与市场数据','https://www.dce.com.cn/'],['CZCE','郑州商品交易所','市场数据与业务公告','https://www.czce.com.cn/'],['GFEX','广州期货交易所','行情与新品种规则','https://www.gfex.com.cn/']];
function bars(m,n=60){let prev=m.price*.91;return Array.from({length:n},(_,i)=>{let open=prev;let delta=(Math.sin((i+m.seed)*2.17)*.007+Math.cos(i*.8+m.seed)*.003+.0016)*m.price;let close=open+delta;prev=close;return{open,close,high:Math.max(open,close)+m.price*(.002+Math.abs(Math.sin(i*3))*.003),low:Math.min(open,close)-m.price*(.002+Math.abs(Math.cos(i*2))*.003),volume:1000+Math.round(Math.abs(Math.sin(i*.72))*4500)}})}
function candleSVG(){let b=bars(selected,period==='D'?60:period==='W'?42:28),w=360,h=240,min=Math.min(...b.map(v=>v.low)),max=Math.max(...b.map(v=>v.high)),y=p=>20+(max-p)/(max-min)*160,x=i=>10+i*300/b.length;let s='<svg viewBox="0 0 360 240" preserveAspectRatio="none" aria-hidden="true">';for(let i=0;i<5;i++){let yy=20+i*40;s+=`<path d="M5 ${yy}H315" stroke="#315369" stroke-opacity=".45" stroke-width=".6"/><text x="321" y="${yy+4}" fill="#688ca7" font-size="9">${(max-i*(max-min)/4).toFixed(0)}</text>`}for(let i=0;i<5;i++)s+=`<path d="M${10+i*76} 10V220" stroke="#294b63" stroke-opacity=".3" stroke-width=".6"/>`;b.forEach((v,i)=>{let c=v.close>=v.open?'#e76d7a':'#43bfb1';s+=`<path d="M${x(i)} ${y(v.high)}V${y(v.low)}" stroke="${c}" stroke-width=".8"/><rect x="${x(i)-1.5}" y="${y(Math.max(v.open,v.close))}" width="3" height="${Math.max(1,Math.abs(y(v.close)-y(v.open)))}" fill="${c}"/><rect x="${x(i)-1.5}" y="${218-v.volume/300}" width="3" height="${v.volume/300}" fill="${c}" opacity=".55"/>`});let pts=b.slice(9).map((_,j)=>`${x(j+9)},${y(b.slice(j,j+10).reduce((a,v)=>a+v.close,0)/10)}`).join(' ');s+=`<polyline points="${pts}" fill="none" stroke="#dcbd75" stroke-width="1.2" opacity=".85"/><text x="12" y="236" fill="#688ca7" font-size="9">-${b.length} ${period==='D'?'日':period==='W'?'周':'月'}</text><text x="265" y="236" fill="#688ca7" font-size="9">演示周期</text></svg>`;return s}
function lineSVG(){return `<svg viewBox="0 0 300 95" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#4286c0" stop-opacity=".35"/><stop offset="1" stop-color="#4286c0" stop-opacity="0"/></linearGradient></defs>${[20,45,70].map(y=>`<path d="M0 ${y}H300" stroke="#294f6a" stroke-width=".5"/>`).join('')}<path d="M0 78L15 72L25 76L35 60L45 66L55 57L65 65L75 41L87 51L96 37L108 46L118 33L129 49L140 45L151 39L161 47L172 37L183 44L194 24L205 31L218 27L230 35L240 20L250 24L263 14L275 21L290 9L300 16V95H0Z" fill="url(#area)"/><path d="M0 78L15 72L25 76L35 60L45 66L55 57L65 65L75 41L87 51L96 37L108 46L118 33L129 49L140 45L151 39L161 47L172 37L183 44L194 24L205 31L218 27L230 35L240 20L250 24L263 14L275 21L290 9L300 16" fill="none" stroke="#6ac5ff" stroke-width="1.3"/></svg>`}
function marketRows(){const list=markets.filter(m=>filter==='all'||m.pool===filter);$('#marketRows').innerHTML=list.map(m=>`<button class="market-row ${selected.code===m.code?'selected':''}" data-code="${m.code}"><span><strong>${m.name}</strong><small>${m.code}</small></span><span class="${m.change>0?'up':'down'}">${m.price.toLocaleString('en-US')}</span><span class="${m.change>0?'up':'down'}">${m.change>0?'+':''}${m.change.toFixed(2)}%</span></button>`).join('')}
function select(code){selected=markets.find(m=>m.code===code)||markets[0];marketRows();$('#chartName').textContent=`${selected.name} ${selected.code}`;$('#chartPrice').textContent=selected.price.toLocaleString('en-US');$('#chartChange').textContent=`${selected.change>0?'+':''}${selected.change.toFixed(2)}%`;$('#chartPrice').style.color=selected.change>0?'var(--red)':'var(--cyan)';$('#chartChange').style.color=selected.change>0?'var(--red)':'var(--cyan)';$('#candleChart').innerHTML=candleSVG();$('#evidenceName').textContent=`${selected.name} · ${selected.direction}`;if(view==='water')renderWorkspace();}
function planPreview(){let last=decisions.filter(d=>d.planId==='demo-cu-v1').at(-1),labels={approve:'已批准模拟记录',reject:'已拒绝',wait:'等待复核'};const html=`<div class="plan-preview"><h3>沪铜 <small class="muted">CU2611</small> <span class="tag">流程演示</span></h3><p>方向 <b>多头示例</b></p><p>计划版本 <b>DEMO · v1.0</b></p><p>状态 <b class="amber">${last?labels[last.action]:'待人工审阅'}</b></p><div class="plan-gates"><span>环境</span><span>阶段</span><span>结构</span><span>触发</span><span>风险</span></div></div>`;$('#planPreview').innerHTML=html;$('#focusCard').innerHTML='<span class="eyebrow">YOUR DECISION</span><h3>今天，只需看清这一件事</h3>'+html+'<button class="primary" data-action="plan">审阅模拟计划 ↗</button>';$('#planCount').innerHTML=(last&&['approve','reject'].includes(last.action)?'00':'01')+' <small>/ 示例</small>'}
function modal(title,html){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=html;$('#detailDialog').showModal()}
function evidence(){modal(`${selected.name} · 证据与反证`,`<span class="tag amber">演示案例 · 不构成当前判断</span><h3>结构先过关，再谈机会</h3><p>当前页面展示的是${esc(selected.code)}的生成示例，用于验证选品种、图表和研究卡联动。价格与K线不是交易所数据。</p><ul class="gate-list"><li>月周日方向证据 <span class="amber">待接入</span></li><li>完成日K MA10触发 <span class="amber">未核验</span></li><li>3—8日结构平台 <span class="amber">待复核</span></li><li>最强反证 <span>真实行情与产业证据缺失</span></li><li>当前权限 <span class="cyan">仅研究</span></li></ul><p>下一检查点：取得官方完成日K，核实板块与真实月份合约，再审查结构。</p><button class="primary" data-action="analyze">计算本地示例结构</button>`)}
function reviewPlan(){let last=decisions.find(d=>d.planId==='demo-cu-v1'&&['approve','reject'].includes(d.action));modal('金 · 模拟计划审阅',`<span class="tag amber">仅体验审批流程 · 不生成委托</span><h3>沪铜 CU2611 · 多头演示计划</h3><div class="detail-grid"><div><span>计划版本</span><b>DEMO-CU-v1</b></div><div><span>有效范围</span><b>本地演示记录</b></div><div><span>入场 / 止损</span><b>未设真实价位</b></div><div><span>账户 / 手数</span><b>未连接 / 不计算</b></div></div><p>这张卡用来体验“系统准备、你拍板”。真实行情、账户风险与交易通道未接入，不会下单。</p><ul class="gate-list"><li>研究证据 <span class="amber">演示</span></li><li>执行许可 <span>真实交易禁止</span></li><li>数据缺失时 <span>默认等待</span></li></ul><div class="dialog-actions"><button class="primary" data-decision="approve" ${last?'disabled':''}>批准模拟记录</button><button data-decision="wait" ${last?'disabled':''}>等待</button><button data-decision="reject" ${last?'disabled':''}>拒绝</button></div>${last?'<p>这张演示计划已处理。记录可在土·执行中查看。</p>':''}`)}
async function decide(action){try{let j=await api('/api/decisions',{planId:'demo-cu-v1',action});if(!j.duplicate)decisions.push(j.record);$('#detailDialog').close();planPreview();if(view!=='home')renderWorkspace();toast(j.duplicate?'该计划已处理，未重复记录':'决定已记录 · 没有提交任何订单')}catch(e){toast(e.message)}}
const titles={fire:['FIRE / OPPORTUNITY RADAR','火 · 机会雷达'],water:['WATER / EVIDENCE RESEARCH','水 · 深度研究'],metal:['METAL / DECISION CENTER','金 · 决策中心'],earth:['EARTH / EXECUTION TRACKING','土 · 执行跟踪'],wood:['WOOD / SYSTEM REVIEW','木 · 复盘迭代'],sources:['DATA / CONNECTIONS','数据与连接']};
function navigate(v){view=v;$('#dashboard').hidden=v!=='home';$('#workspace').hidden=v==='home';$$('.sidebar [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v!=='home')renderWorkspace();window.scrollTo({top:0,behavior:'smooth'})}
function taskCards(){return tasks.length?tasks.slice().reverse().map(t=>`<div class="work-item"><div><b>${esc(t.result?.title||({scan:'扫描市场',analysis:'分析品种',risk:'风险检查',review:'执行审计'}[t.kind]))}</b><p>${esc(t.result?.summary||'后台任务处理中')}</p><small>${new Date(t.created).toLocaleTimeString('zh-CN')} · 本地演示数据</small></div><span class="tag ${t.status==='completed'?'cyan':'amber'}">${t.status==='completed'?'已完成':t.status==='failed'?'失败':'处理中'}</span></div>`).join(''):'<div class="no-data"><strong>◎</strong>任务尚未开始<br>你可以在通话时说“扫描机会”，或点击扫描按钮。</div>'}
function renderWorkspace(){let [ey,t]=titles[view];$('#workEyebrow').textContent=ey;$('#workTitle').textContent=t;let html='';if(view==='fire'){html=`<div class="work-banner">全市场扫描尚未接入。下面是8个演示品种，可运行真实的本地MA10计算，验证工作流程。</div><div class="mini-kpi"><div><b>08</b><span>演示品种</span></div><div><b>02</b><span>界面核心候选</span></div><div><b>00</b><span>完整交易许可</span></div><button class="primary" data-action="scan">扫描演示数据</button></div><table class="work-table"><thead><tr><th>品种</th><th>板块</th><th>示例状态</th><th>操作</th></tr></thead><tbody>${markets.map(m=>`<tr><td>${m.name} <small class="muted">${m.code}</small></td><td>${m.sector}</td><td>${m.direction}</td><td><button data-research="${m.code}" class="quiet">分析 ↗</button></td></tr>`).join('')}</tbody></table><h3>扫描任务</h3><div class="work-list">${taskCards()}</div>`}
if(view==='water'){html=`<div class="work-banner">${selected.name} ${selected.code} · 本地演示结构。真实产业、库存、基差和公告证据待接入。</div><div class="work-grid"><article class="work-card"><span class="eyebrow">01 / STRUCTURE</span><h3>图形与环境</h3><p>完成月周日K → MA10方向 → 平台边界 → 等待唯一主触发。</p><button class="primary" data-action="analyze">分析 ${selected.name}</button></article><article class="work-card"><span class="eyebrow">02 / EVIDENCE</span><h3>支持与反证</h3><p>主驱动、三个关键变量、最强反证与下一检查点。不用故事代替价格确认。</p><button class="quiet" data-action="evidence">展开证据卡</button></article><article class="work-card"><span class="eyebrow">03 / PERMISSION</span><h3>权限保持独立</h3><p>研究排序不是入场许可。缺真实数据时，不计算手数，不授予交易权。</p><span class="tag amber">等待数据</span></article></div><h3>研究任务</h3><div class="work-list">${taskCards()}</div>`}
if(view==='metal'){html=`<div class="work-banner">你的决定绑定具体计划版本。当前只体验模拟审批；真实订单接口未连接。</div><div class="work-grid"><article class="work-card"><span class="tag">DEMO · v1.0</span><h3>沪铜 · 多头示例</h3><p>五道门、结构止损、账户与组合风险，应在正式计划中全部核验。</p><button class="primary" data-action="plan">审阅模拟计划 ↗</button></article><article class="work-card"><h3>规则硬门</h3><p>环境 → 阶段 → 结构 → 完成日K触发 → 风险。任何一门未知，正式计划即等待。</p></article><article class="work-card"><h3>你保留的权限</h3><p>批准、等待、拒绝。通话中的含糊“可以”不会触发交易或替代明确审批。</p></article></div>`}
if(view==='earth'){html=`<div class="work-banner">账户未连接 · 没有真实委托或成交。下面是你在此原型内作出的演示决定。</div><div class="mini-kpi"><div><b>${decisions.length.toString().padStart(2,'0')}</b><span>演示决定</span></div><div><b>00</b><span>委托提交</span></div><div><b>—</b><span>真实持仓未知</span></div></div><div class="work-list">${decisions.length?decisions.slice().reverse().map(d=>`<div class="work-item"><div><b>沪铜 · DEMO-CU-v1</b><p>${{approve:'批准模拟记录',wait:'等待复核',reject:'拒绝计划'}[d.action]} · 未生成订单</p><small>${new Date(d.time).toLocaleString('zh-CN')}</small></div><span class="tag">演示</span></div>`).join(''):'<div class="no-data">暂无记录，先在金·决策中审阅模拟计划。</div>'}</div><h3>后台工作队列</h3><div class="work-list">${taskCards()}</div>`}
if(view==='wood'){html=`<div class="work-banner">贝叶斯模型尚无真实交易样本。先记录事实与偏差，再更新判断；规则升级始终由你批准。</div><div class="work-grid"><article class="work-card"><span class="eyebrow">SAMPLES</span><div class="metric">0 <small>笔</small></div><h3>可比真实样本</h3><p>演示行情和模拟审批不计入业绩或胜率。</p></article><article class="work-card"><span class="eyebrow">POSTERIOR</span><div class="metric">—</div><h3>后验尚不可用</h3><p>没有校准证据，不用主观加分伪装成交易概率。</p></article><article class="work-card"><span class="eyebrow">VERSION</span><div class="metric">v1.0</div><h3>规则冻结</h3><p>木提出变更 → 影子验证 → 你批准 → 新版本。一次只改一个变量。</p><button class="primary" data-action="audit">审计本地演示记录</button></article></div><h3>审计结果</h3><div class="work-list">${taskCards()}</div>`}
if(view==='sources'){html=`<div class="work-banner">国内行情待接入；上期所公告已连接。新增海外市场与宏观数据入口，独立显示真实来源。</div><div class="work-grid"><div class="work-card"><h3>行情与交易</h3><p>官方日终：待接入<br>授权实时行情：待接入<br>期货账户：未连接<br>数据集：本地演示</p></div><div class="work-card"><h3>AI 实时通话</h3><p>${configured?'服务端检测到配置，可尝试接通；尚需实际音频验收。':'服务端尚未配置语音API。可先使用本地文字指令及浏览器语音体验。'}</p><button class="primary" data-action="call">打开通话</button></div><div class="work-card"><h3>本地与隐私</h3><p>页面仅在本机运行。启用语音后音频可能交由浏览器或AI语音服务处理；页面不保存音频文件。</p></div></div><h3>官方来源入口</h3><div class="work-list">${sourceList.map(s=>`<a class="work-item" href="${s[3]}" target="_blank" rel="noopener"><div><b>${s[1]}</b><p>${s[2]}</p></div><span class="tag">未接入 ↗</span></a>`).join('')}</div>`}
$('#workspaceBody').innerHTML=html;if(view==='sources'){mountDataHub();mountLiveMarket();}}
async function refresh(){try{let s=await api('/api/status');configured=s.realtimeConfigured;tasks=s.tasks;decisions=s.decisions;$('#health').textContent='本地服务在线 · 行情未接入';$('#runningCount').textContent=tasks.filter(t=>t.status==='running').length;planPreview();return s}catch{ $('#health').textContent='本地服务离线';throw Error('本地服务未连接，请通过启动脚本打开页面')}}
async function runTask(kind='scan'){try{const j=await api('/api/tasks',{kind,code:selected.code});tasks.push(j);$('#taskPulse').innerHTML='<span></span> 后台研究任务已提交';toast('任务已提交，对话和页面操作可继续');let result;for(let i=0;i<20;i++){result=await api('/api/tasks/'+j.id);if(result.status!=='running')break;await new Promise(r=>setTimeout(r,500))}await refresh();if(view!=='home')renderWorkspace();if(result.status==='completed'){ $('#taskPulse').innerHTML='<span></span> '+esc(result.result.title);voice.addMessage('assistant',result.result.summary);return result.result.summary}return '任务仍在运行，可在执行跟踪中查看。'}catch(e){toast(e.message);return e.message}}
async function command(text){if(/扫描|找机会|筛选/.test(text))return await runTask('scan');if(/风险|仓位|止损/.test(text))return await runTask('risk');if(/复盘|审计|迭代/.test(text))return await runTask('review');if(/分析|研究|品种/.test(text)){for(const m of markets)if(text.includes(m.name)||text.toUpperCase().includes(m.code))select(m.code);return await runTask('analysis')}if(/决策|计划|批准|下单|买入|卖出/.test(text)){navigate('metal');return '已打开决策中心。当前只能审阅演示计划，不会生成真实订单。请在计划卡内明确操作。'}if(/你好|在吗|贾维斯|jarvis/i.test(text))return '我在。你可以让我扫描机会、分析当前品种、检查风险或审计记录。当前是本地固定指令体验，使用演示数据。';return '本地模式目前支持“扫描机会”“分析沪铜”“检查风险”“复盘记录”。自由对话需要接入AI实时通话。'}
const voice=new VoiceController({api,command,onTool:async()=>{await refresh();if(view!=='home')renderWorkspace()},toast,isConfigured:()=>configured});
function settings(){modal('驾驶舱设置',`<div class="settings-row"><span>降低动态效果</span><input type="checkbox" id="reduceMotion" ${document.body.classList.contains('reduced')?'checked':''}></div><div class="settings-row"><span>专注决策模式</span><input type="checkbox" id="focusSetting" ${document.body.classList.contains('focus')?'checked':''}></div><h3>通话与工作</h3><p>本地体验：固定指令、浏览器语音识别与朗读。AI实时通话：通过服务端连接语音模型，支持对话中调用研究工具。</p><p>语音服务状态：<span class="${configured?'cyan':'amber'}">${configured?'已检测到服务端配置':'未配置'}</span>。密钥仅放服务端，不输入浏览器。</p><h3>运行范围</h3><p>仅本机研究原型 · 演示行情 · 没有账户或下单接口。页面关闭后通话结束；服务进程停止后后台任务也停止。</p>`)}
function focusToggle(value){const v=value??!document.body.classList.contains('focus');document.body.classList.toggle('focus',v);$('#focusMode').textContent=v?'◎ 全息模式':'◎ 专注模式';localStorage.setItem('jarvis-focus',String(v))}
$('#focusMode').onclick=()=>focusToggle();$('#settings').onclick=settings;$('#closeDialog').onclick=()=>$('#detailDialog').close();$('#detailDialog').addEventListener('click',e=>{if(e.target===$('#detailDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('#reviewPlan').onclick=reviewPlan;$('#chartDetails').onclick=evidence;$('#viewEvidence').onclick=evidence;$('#callOrb').onclick=()=>voice.open();$('#textChat').onclick=()=>voice.open();$('#navCall').onclick=()=>voice.open();
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.code)select(b.dataset.code);if(b.dataset.research){select(b.dataset.research);navigate('water')}if(b.dataset.filter){filter=b.dataset.filter;$$('#marketTabs button').forEach(x=>x.classList.toggle('active',x===b));marketRows()}if(b.dataset.period){period=b.dataset.period;$$('#periodTabs button').forEach(x=>x.classList.toggle('active',x===b));$('#candleChart').innerHTML=candleSVG()}if(b.dataset.decision)decide(b.dataset.decision);if(b.dataset.action){const a=b.dataset.action;if(a==='scan')runTask('scan');if(a==='analyze'){$('#detailDialog').close();runTask('analysis')}if(a==='audit')runTask('review');if(a==='plan')reviewPlan();if(a==='evidence')evidence();if(a==='call')voice.open()}});
document.addEventListener('change',e=>{if(e.target.id==='reduceMotion'){document.body.classList.toggle('reduced',e.target.checked);localStorage.setItem('jarvis-motion',String(e.target.checked))}if(e.target.id==='focusSetting')focusToggle(e.target.checked)});
function tick(){let now=new Date();$('#clock').textContent=now.toLocaleTimeString('en-GB',{timeZone:'Asia/Shanghai'});$('#date').textContent=now.toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'}).replaceAll('-','.')+'  '+now.toLocaleDateString('en-US',{weekday:'short',timeZone:'Asia/Shanghai'}).toUpperCase()};tick();setInterval(tick,1000);
$('#evidencePlot').innerHTML=lineSVG();focusToggle(localStorage.getItem('jarvis-focus')==='true');document.body.classList.toggle('reduced',localStorage.getItem('jarvis-motion')==='true');
try{markets=(await api('/api/market')).markets;select('CU2611');await refresh();}catch(e){toast(e.message);$('#marketRows').innerHTML='<div class="no-data">本地服务未连接，请使用启动脚本打开。</div>'}
window.addEventListener('beforeunload',()=>voice.stop());
